insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'g3_health_v1'
from (values
('115.15.b.1',3,'Which body system fights germs and helps protect you from sickness?','["immune system", "skeletal system", "digestive system", "muscular system"]'::jsonb,0,'The immune system defends the body.','original'),
('115.15.b.1',3,'Which organ in the nervous system controls thinking and body movement?','["kidney", "brain", "bone", "stomach"]'::jsonb,1,'The brain directs the body.','original'),
('115.15.b.1',3,'In the digestive system, food travels from the mouth through the...','["lungs to the heart", "brain to the skin", "esophagus to the stomach", "ears to the nose"]'::jsonb,2,'The esophagus carries food down.','original'),
('115.15.b.1',3,'Which body system removes waste from the blood and makes urine?','["muscular system", "respiratory system", "skeletal system", "urinary system"]'::jsonb,3,'Kidneys filter blood.','original'),
('115.15.b.2.A',3,'Why is it helpful to talk with a parent or doctor before making a big health choice?','["they can give accurate advice", "they are never right", "they will decide for you always", "they dislike questions"]'::jsonb,0,'Trusted adults share good information.','original'),
('115.15.b.2.A',3,'Seeking help with health decisions is smart because adults and professionals...','["always guess", "know reliable information", "never listen", "only tell jokes"]'::jsonb,1,'Experts help you decide well.','original'),
('115.15.b.2.B',3,'Which source is a reliable way to learn about health?','["a rumor from a stranger", "a made-up story", "a school nurse", "a random pop-up ad"]'::jsonb,2,'Nurses give accurate information.','original'),
('115.15.b.2.B',3,'Which method can help you find health information?','["asking a stranger", "flipping a coin", "guessing", "asking a doctor or using a trusted website"]'::jsonb,3,'Reliable sources give accurate facts.','original'),
('115.15.b.2.C',3,'A benefit of choosing to wash your hands is that you...','["are less likely to get sick", "grow wings", "get taller", "lose a tooth"]'::jsonb,0,'Good choices protect health.','original'),
('115.15.b.2.C',3,'Making good health decisions now can help you...','["lose friends", "feel better and stay well", "get lost", "forget your homework"]'::jsonb,1,'Decisions have lasting benefits.','original'),
('115.15.b.2.D',3,'Taking personal responsibility for your health means you...','["never brush your teeth", "ignore doctors", "do your part to stay healthy", "blame others for being sick"]'::jsonb,2,'Responsibility means acting for yourself.','original'),
('115.15.b.2.D',3,'Which shows personal responsibility for health?','["skipping every meal", "staying up all night", "never washing up", "packing a healthy lunch and drinking water"]'::jsonb,3,'Healthy habits show responsibility.','original'),
('115.15.b.2.E',3,'Washing your hands for about twenty seconds helps remove...','["germs", "your fingerprints", "your freckles", "your nails"]'::jsonb,0,'Washing removes germs.','original'),
('115.15.b.2.E',3,'Which disease can spread from person to person?','["a broken arm", "the flu", "sunburn", "a bruise"]'::jsonb,1,'Flu is a contagious illness.','original'),
('115.15.b.2.E',4,'Vaccines work by helping your body...','["see better", "forget old illnesses", "build protection before you meet a germ", "grow bigger muscles"]'::jsonb,2,'Vaccines train the immune system.','original'),
('115.15.b.2.F',4,'Asthma, diabetes, and epilepsy are diseases that are...','["spread by touching", "spread by sneezing", "spread by sharing food", "not spread from person to person"]'::jsonb,3,'They are not contagious.','original'),
('115.15.b.2.F',4,'Which is true about asthma?','["you cannot catch it from a friend", "it spreads by food", "it spreads by coughing", "it spreads by handshake"]'::jsonb,0,'Asthma is noncommunicable.','original'),
('115.15.b.2.G',4,'A vector is an animal, like a tick or mosquito, that...','["helps you sleep", "carries germs from one host to another", "grows plants", "makes music"]'::jsonb,1,'Vectors carry disease.','original'),
('115.15.b.2.G',4,'To prevent mosquito bites, you can...','["stand near standing water", "go outside with bare skin at dusk", "use insect repellent and wear long sleeves", "collect old tires of water"]'::jsonb,2,'Repellent and covering skin help.','original'),
('115.15.b.2.G',4,'After finding a tick on your skin, you should...','["burn it", "squash it", "ignore it", "ask an adult to remove it safely"]'::jsonb,3,'Adults should remove ticks properly.','original'),
('115.15.b.3.A',3,'Which message communicates an emotion in a healthy way?','["\"I feel frustrated when my turn is skipped.\"", "\"You always cheat!\"", "\"Nobody cares.\"", "\"I hate everyone!\""]'::jsonb,0,'Calm I-statements share feelings.','original'),
('115.15.b.3.A',3,'Telling a friend "I need some space right now" is a healthy way to share...','["a trick", "a need", "a joke", "a lie"]'::jsonb,1,'It communicates a need respectfully.','original'),
('115.15.b.3.B',4,'Before acting on a strong feeling, a good way to check your thoughts is to...','["act without thinking", "blame others", "pause and ask whether they are true and helpful", "ignore your body"]'::jsonb,2,'Thought checking prevents poor choices.','original'),
('115.15.b.3.B',3,'Deep breathing and stretching are examples of...','["tricks", "bad habits", "punishments", "calming practices"]'::jsonb,3,'Calming practices help self-management.','original'),
('115.15.b.3.C',4,'Brain maturation means your brain...','["keeps changing and getting more skilled as you grow", "stops working", "never learns", "shrinks every year"]'::jsonb,0,'The brain develops through childhood.','original'),
('115.15.b.3.C',4,'Learning new skills, sleeping, and eating well help your brain...','["shrink", "develop", "stop", "forget"]'::jsonb,1,'Healthy habits support brain growth.','original'),
('115.15.b.3.D',3,'A healthy influence from a friend would be...','["pressuring you to lie", "teasing you", "encouraging you to study", "daring you to break rules"]'::jsonb,2,'Healthy influence supports good choices.','original'),
('115.15.b.3.D',3,'A harmful influence from others would be...','["helping you clean up", "sharing a snack", "inviting you to read", "pressuring you to try something unsafe"]'::jsonb,3,'Pressure to do unsafe things is harmful.','original'),
('115.15.b.3.E',3,'A healthy friendship includes...','["trust and respect", "jealousy and secrets", "name-calling", "control and fear"]'::jsonb,0,'Healthy friends trust and respect.','original'),
('115.15.b.3.E',3,'An unhealthy friendship may involve a friend who...','["apologizes sincerely", "bosses you and makes you feel bad", "shares fairly", "listens to you"]'::jsonb,1,'Controlling behavior is unhealthy.','original'),
('115.15.b.3.F',3,'Respectful communication helps people...','["feel afraid", "argue more", "understand each other", "feel ignored"]'::jsonb,2,'Respect improves understanding.','original'),
('115.15.b.3.F',3,'Which is a value of respectful communication?','["it spreads rumors", "it ends friendships", "it hurts feelings", "it builds trust"]'::jsonb,3,'Respect builds relationships.','original'),
('115.15.b.3.G',4,'Two students see the same test. One feels excited, the other nervous. This shows that people...','["can experience situations differently", "have no feelings", "always feel the same", "never learn"]'::jsonb,0,'Perspectives differ.','original'),
('115.15.b.3.G',3,'To understand how a classmate feels, you can...','["decide without asking", "listen to their point of view", "ignore them", "laugh at them"]'::jsonb,1,'Listening builds empathy.','original'),
('115.15.b.3.H',3,'A good strategy to resolve a conflict is to...','["walk away without talking", "call names", "listen, share your side, and find a compromise", "tell everyone"]'::jsonb,2,'Compromise resolves conflicts.','original'),
('115.15.b.3.H',4,'Using "I" statements during a disagreement helps you...','["stop listening", "blame the other person", "walk away", "explain feelings without blaming"]'::jsonb,3,'I-statements reduce blame.','original'),
('115.15.b.4.A',3,'Self-esteem is how you...','["feel about yourself", "spell words", "look in photos", "run a race"]'::jsonb,0,'Self-esteem is self-worth.','original'),
('115.15.b.4.A',4,'Self-esteem can grow when you...','["quit when it is hard", "practice a skill and improve", "compare yourself to everyone", "put yourself down"]'::jsonb,1,'Success builds confidence.','original'),
('115.15.b.4.B',3,'Why should you ask a trusted adult for guidance when setting a goal?','["they will say no always", "they dislike goals", "they can help you plan realistic steps", "they will do it for you"]'::jsonb,2,'Adults offer helpful advice.','original'),
('115.15.b.4.B',3,'A trusted adult can help you set a goal by...','["ignoring you", "choosing a goal for you every time", "telling you to quit", "helping you break it into small steps"]'::jsonb,3,'Guidance helps plan.','original'),
('115.15.b.5.A',4,'A person with a long-term health condition such as asthma can manage it by...','["following their care plan", "ignoring symptoms", "hiding it", "skipping medicine"]'::jsonb,0,'Care plans help manage conditions.','original'),
('115.15.b.5.A',4,'Checking blood sugar and following a care plan is a way to manage...','["a haircut", "diabetes", "a cold", "a bruise"]'::jsonb,1,'Daily care helps manage diabetes.','original'),
('115.15.b.5.B',3,'You can support a classmate who learns differently by...','["laughing", "ignoring them", "offering help and being patient", "doing it for them without asking"]'::jsonb,2,'Support means helping kindly.','original'),
('115.15.b.5.B',3,'Using clear directions and extra time can support someone who needs...','["a bigger desk", "a louder voice", "more homework", "a different way to learn"]'::jsonb,3,'Accommodations help learners.','original'),
