('115.15.b.14.B',3,'Smoking and vaping can cause long-term damage to the...','["lungs", "toes", "ears", "knees"]'::jsonb,0,'Lungs suffer harm.','original'),
('115.15.b.14.B',4,'Inhalants such as spray paint fumes can damage the...','["toenails", "brain and organs", "hair color", "height"]'::jsonb,1,'Inhalants are toxic.','original'),
