('115.15.b.16',3,'If a person takes too much of a harmful drug, you should call...','["911", "a friend only", "nobody", "a pet"]'::jsonb,0,'911 sends emergency help.','original'),
('115.15.b.16',3,'Poison Control can help if someone...','["lost a toy", "swallowed something harmful", "is hungry", "got a haircut"]'::jsonb,1,'Poison Control gives guidance.','original'),
('115.15.b.17.A',3,'A friend can influence your choice about drugs by...','["sitting next to you", "knowing your homework", "encouraging you to say no or pressuring you to try", "sharing a pencil"]'::jsonb,2,'Friends can push either way.','original'),
('115.15.b.17.A',4,'Having friends who avoid drugs makes it easier to...','["break rules", "stay up late", "forget your name", "make healthy choices"]'::jsonb,3,'Positive peers help.','original'),
('115.15.b.17.B',4,'Reporting is telling an adult when someone could be hurt, while tattling is telling...','["only to get someone in trouble", "about a fire", "because someone is hurt", "about an emergency"]'::jsonb,0,'Reporting protects; tattling is petty.','original'),
('115.15.b.17.B',4,'Why report a friend who is in danger from drugs?','["to win", "an adult can help keep them safe", "to get them in trouble", "to be mean"]'::jsonb,1,'Reporting saves lives.','original'),
('115.15.b.18',3,'A refusal skill for an unsafe offer is to say no, give a reason, and...','["try it a little", "laugh", "leave the situation", "stay and watch"]'::jsonb,2,'Leaving is part of refusing.','original'),
('115.15.b.18',3,'Which is a good way to refuse a drug offer?','["\"Maybe next time.\"", "\"Sure, why not?\"", "\"I''ll think about it.\"", "\"No thanks. I don''t use that.\""]'::jsonb,3,'A clear no works best.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Health Education' and d.language = 'en'
on conflict (fingerprint) do nothing;
